// shipping.js.
export const FREE_FROM = 500;
export function shipping(total) {
  if (!Number.isFinite(total) || total < 0) throw new RangeError("total must be >= 0");
  return total >= FREE_FROM ? 0 : 50;
}

// shipping.test.js (Vitest or Jest syntax).
import { describe, it, expect } from "vitest";
import { shipping } from "./shipping.js";

describe("shipping", () => {
  it("charges 50 on a normal small order", () => expect(shipping(200)).toBe(50));
  it("charges 50 for an empty cart", () => expect(shipping(0)).toBe(50));
  it("charges 50 just below the threshold", () => expect(shipping(499.99)).toBe(50));
  it("is free exactly at the threshold", () => expect(shipping(500)).toBe(0));
  it("rejects negative totals", () => expect(() => shipping(-1)).toThrow(RangeError));
  it("rejects NaN", () => expect(() => shipping(NaN)).toThrow(RangeError));
});
```

